/* Quiz bank, mock oral and progress. Data: assets/quiz.json (generated by quiz/bank.py). */
(function () {
  let BANK = null;
  const TYPE = { mcq: 'Concepto', explain: 'Explica / deriva', num: 'Cálculo' };
  const statusLabel = ['fallada', 'a medias', 'dominada'];

  async function load() {
    if (BANK) return BANK;
    const r = await fetch('assets/quiz.json'); BANK = await r.json();
    const counts = {}; BANK.questions.forEach(q => { (counts[q.topic] = counts[q.topic] || { ids: [] }).ids.push(q.id); });
    ERA.store.set('era-topic-counts', counts); ERA.updateBadges();
    return BANK;
  }
  // populate badges on every page
  document.addEventListener('DOMContentLoaded', () => { if (!ERA.topicCounts()) load().catch(() => {}); });

  const esc = s => String(s);
  function parseNum(str) {
    if (typeof str !== 'string') return NaN;
    const t = str.trim().replace(/\s/g, '').replace('−', '-').replace(',', '.');
    return /^[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?$/.test(t) ? parseFloat(t) : NaN;   // whole string must be a number
  }

  function statusChip(id) {
    const p = ERA.progress()[id]; if (p === undefined) return '<span class="qstatus">sin hacer</span>';
    return `<span class="qstatus s${p}">${statusLabel[p]}</span>`;
  }

  /* Render one question card; onDone(score 0..2) called when answered/self-rated. */
  function card(q, opts = {}) {
    const div = document.createElement('div'); div.className = 'qcard'; div.id = 'q-' + q.id;
    const head = `<div class="qhead"><span class="qtype">${TYPE[q.type]} · ${BANK.topics[q.topic]}</span><span class="st">${opts.hideStatus ? '' : statusChip(q.id)}</span></div>`;
    let body = `<p class="qtext">${esc(q.q)}</p>`;
    if (q.type === 'mcq') {
      body += '<div class="qopts">' + q.opts.map((o, i) => `<button class="qopt" data-i="${i}">${String.fromCharCode(65 + i)}. ${esc(o)}</button>`).join('') + '</div><div class="fb"></div>';
    } else if (q.type === 'num') {
      body += `<div class="qnum"><input type="text" inputmode="decimal" aria-label="Respuesta" placeholder="tu resultado"> <span>${esc(q.unit || '')}</span>
        <button class="wbtn primary chk">Comprobar</button><button class="wbtn show">Ver solución</button></div><div class="fb"></div>`;
    } else {
      body += `<div class="qrate"><button class="wbtn primary rev">Ver respuesta modelo</button></div><div class="model" hidden></div>`;
    }
    div.innerHTML = head + body;
    const setStatus = s => { if (!opts.noSave) ERA.setProgress(q.id, s); const st = div.querySelector('.st'); if (st && !opts.hideStatus) st.innerHTML = statusChip(q.id); opts.onDone && opts.onDone(s); };
    if (q.type === 'mcq') {
      div.querySelectorAll('.qopt').forEach(b => b.addEventListener('click', () => {
        if (div.dataset.done) return; div.dataset.done = 1;
        const i = +b.dataset.i, ok = i === q.a;
        div.querySelectorAll('.qopt')[q.a].classList.add('correct'); if (!ok) b.classList.add('wrong');
        const fb = div.querySelector('.fb'); fb.className = 'qfeedback ' + (ok ? 'ok' : 'bad');
        fb.innerHTML = `<strong>${ok ? 'Correcto.' : 'No.'}</strong> ${esc(q.ex)}`; ERA.renderMath(fb); setStatus(ok ? 2 : 0);
      }));
    } else if (q.type === 'num') {
      const inp = div.querySelector('input'), fb = div.querySelector('.fb');
      const check = () => {
        const v = parseNum(inp.value); if (!isFinite(v)) { fb.className = 'qfeedback'; fb.textContent = 'Escribe un número (coma o punto decimal).'; return; }
        const err = Math.abs(v - q.ans) / Math.max(Math.abs(q.ans), 1e-12), ok = err <= q.tol, close = !ok && err <= 5 * q.tol;
        fb.className = 'qfeedback ' + (ok ? 'ok' : 'bad');
        const ansStr = Math.abs(q.ans) >= 1e-3 && Math.abs(q.ans) < 1e6 ? q.ans.toPrecision(4) : q.ans.toExponential(3);
        fb.innerHTML = `<strong>${ok ? 'Correcto' : close ? 'Casi (revisa redondeos o unidades)' : 'Incorrecto'}</strong>: valor de referencia ${ansStr.replace('.', ',')} ${esc(q.unit || '')} (tolerancia ±${Math.round(q.tol * 100)} %).<br>${esc(q.sol)}`;
        ERA.renderMath(fb); setStatus(ok ? 2 : close ? 1 : 0);
      };
      div.querySelector('.chk').addEventListener('click', check);
      inp.addEventListener('keydown', e => { if (e.key === 'Enter') check(); });
      div.querySelector('.show').addEventListener('click', () => { fb.className = 'qfeedback'; fb.innerHTML = esc(q.sol); ERA.renderMath(fb); setStatus(0); });
    } else {
      const m = div.querySelector('.model');
      div.querySelector('.rev').addEventListener('click', ev => {
        m.hidden = false; ev.target.remove();
        m.innerHTML = `<div class="qmodel">${q.model}<p><strong>Puntos que se esperan:</strong> ${q.keys.map(esc).join(' · ')}</p></div>
          <div class="qrate">¿Cómo te ha salido? <button class="wbtn" data-s="2">Bien</button><button class="wbtn" data-s="1">A medias</button><button class="wbtn" data-s="0">Mal</button></div>`;
        ERA.renderMath(m);
        m.querySelectorAll('[data-s]').forEach(b => b.addEventListener('click', () => { m.querySelectorAll('[data-s]').forEach(x => x.disabled = true); b.classList.add('primary'); setStatus(+b.dataset.s); }));
      });
    }
    return div;
  }

  async function practice() {
    const bank = await load();
    const ft = document.getElementById('f-topic'), fy = document.getElementById('f-type'), fs = document.getElementById('f-status'), list = document.getElementById('qlist');
    ft.innerHTML = '<option value="">Todos</option>' + Object.entries(bank.topics).map(([k, v]) => `<option value="${k}">${v}</option>`).join('');
    const hashTopic = new URLSearchParams(location.search).get('t'); if (hashTopic) ft.value = hashTopic;
    const render = () => {
      const p = ERA.progress();
      const qs = bank.questions.filter(q => (!ft.value || q.topic === ft.value) && (!fy.value || q.type === fy.value) && (fs.value !== 'todo' || (p[q.id] ?? 0) < 2));
      document.getElementById('f-count').textContent = `${qs.length} preguntas`;
      list.innerHTML = ''; qs.forEach(q => list.appendChild(card(q)));
      ERA.renderMath(list);
    };
    [ft, fy, fs].forEach(e => e.addEventListener('change', render)); render();
  }

  function shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

  async function mock() {
    const bank = await load(), area = document.getElementById('mock-area');
    let timer = null;
    document.getElementById('m-start').addEventListener('click', () => {
      const scope = document.getElementById('m-scope').value, n = +document.getElementById('m-n').value, T = +document.getElementById('m-t').value;
      const scopes = { all: Object.keys(bank.topics), theory: ['t01', 't02', 't03', 't04', 't05', 't06', 't07', 't08', 't09'],
        A1: ['A1', 't02', 't03', 't04', 't05'], A2: ['A2', 't03', 't05'], A3: ['A3', 't06', 't07', 't08', 't09'] };
      const topics = scopes[scope];
      const pool = {}; topics.forEach(t => pool[t] = shuffle(bank.questions.filter(q => q.topic === t && q.type !== 'num')));
      // round-robin over topics (assignment topic first for assignment orals) so every topic is drawn before any repeats
      const order = scope.startsWith('A') ? [topics[0]].concat(shuffle(topics.slice(1))) : shuffle(topics.slice());
      const picked = []; let k = 0;
      while (picked.length < n && Object.values(pool).some(a => a.length)) { const t = order[k % order.length]; if (pool[t].length) picked.push(pool[t].pop()); k++; }
      if (scope.startsWith('A')) { const first = picked.filter(q => q.topic === scope), rest = shuffle(picked.filter(q => q.topic !== scope)); picked.splice(0, picked.length, ...first.slice(0, 1), ...shuffle(first.slice(1).concat(rest))); }
      let i = 0; const scores = [];
      const next = () => {
        clearInterval(timer); area.innerHTML = '';
        if (i >= picked.length) {
          const tot = scores.reduce((a, b) => a + b, 0), pct = Math.round(100 * tot / (2 * picked.length));
          area.innerHTML = `<div class="card"><h3>Resultado del simulacro: ${pct} %</h3><p>${picked.map((q, j) => `${j + 1}. ${BANK.topics[q.topic]}: <span class="qstatus s${scores[j]}">${statusLabel[scores[j]]}</span>`).join('<br>')}</p>
            <p>Repasa los temas con «fallada» o «a medias» en la pestaña Practicar (filtro «Pendientes o falladas»).</p></div>`;
          return;
        }
        const q = picked[i];
        const top = document.createElement('div'); top.className = 'qtoolbar';
        top.innerHTML = `<strong>Pregunta ${i + 1} de ${picked.length}</strong><span class="timer" aria-live="polite"></span><button class="wbtn" id="m-skip">Pasar</button>`;
        area.appendChild(top);
        const c = card(q, { onDone: s => { scores[i] = s; clearInterval(timer); const nb = document.createElement('button'); nb.className = 'wbtn primary'; nb.textContent = i + 1 < picked.length ? 'Siguiente pregunta' : 'Ver resultado'; nb.onclick = () => { i++; next(); }; c.appendChild(nb); } });
        area.appendChild(c); ERA.renderMath(area);
        let left = T; const tEl = top.querySelector('.timer');
        const tick = () => { tEl.textContent = `${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')}`; if (left <= 0) { clearInterval(timer); tEl.textContent = 'Tiempo'; tEl.style.color = 'var(--bad)'; const b = c.querySelector('.rev'); if (b) b.click(); } left--; };
        tick(); timer = setInterval(tick, 1000);
        top.querySelector('#m-skip').onclick = () => { scores[i] = 0; ERA.setProgress(q.id, 0); i++; next(); };
      };
      next();
    });
  }

  async function progress() {
    const bank = await load(), area = document.getElementById('progress-area'), p = ERA.progress();
    let html = '<table class="data progress-table"><thead><tr><th>Tema</th><th>Hechas</th><th>Dominadas</th><th>Dominio</th></tr></thead><tbody>';
    Object.entries(bank.topics).forEach(([t, name]) => {
      const qs = bank.questions.filter(q => q.topic === t), done = qs.filter(q => p[q.id] !== undefined).length, good = qs.filter(q => p[q.id] === 2).length;
      const pct = Math.round(100 * qs.reduce((a, q) => a + (p[q.id] || 0), 0) / (2 * qs.length));
      html += `<tr><td><a href="quiz.html?t=${t}">${name}</a></td><td>${done}/${qs.length}</td><td>${good}</td><td><div class="bar"><span style="width:${pct}%"></span></div> ${pct} %</td></tr>`;
    });
    area.innerHTML = html + '</tbody></table>';
  }

  document.addEventListener('DOMContentLoaded', () => {
    const app = document.getElementById('quiz-app'); if (!app) return;
    const modes = ['practice', 'mock', 'progress'];
    const show = m => { modes.forEach(x => { document.getElementById('mode-' + x).hidden = x !== m; });
      app.querySelectorAll('[data-mode]').forEach(b => b.classList.toggle('primary', b.dataset.mode === m)); if (m === 'progress') progress(); };
    app.querySelectorAll('[data-mode]').forEach(b => b.addEventListener('click', () => show(b.dataset.mode)));
    document.getElementById('p-reset').addEventListener('click', () => { if (confirm('¿Borrar todo tu progreso guardado en este navegador?')) { ERA.store.set('era-progress', {}); progress(); ERA.updateBadges(); } });
    practice(); mock(); progress();
    if (location.hash === '#mock') show('mock');
  });
})();
